\label{def:Ulrich} Let $X\subset \mathbb P^N$ be a smooth variety of dimension $n$  and let $H$  be a hyperplane section of $X$.
A vector bundle $\mathcal{U}$  on $X$ is said to be  {\em Ulrich} with respect to $H$ if
\begin{eqnarray*}
H^{i}(X, \mathcal{U}(-jH))=0 \quad \text{for}  \quad i=0, \cdots, n \quad  \text{and} \quad 1 \leqslant j \leqslant \dim X.
\end{eqnarray*}

\label{pullback} Let $(Y,H)$ be a polarized surface with $H$ very ample and let $\mathcal E$ be a rank two vector bundle on $Y$ such that $\mathcal E$ is (very) ample and spanned. 
Let $\mathcal F$ be a rank $r \geqslant 1$ vector bundle on $Y$. Then on the $3$-fold scroll  $X \cong \mathbb{P}(\mathcal E)\xrightarrow{\pi} Y$, 
the vector bundle $\mathcal U:= \xi \otimes \pi^*\mathcal F$ is Ulrich with respect to $\xi$, where  $\xi$ denotes the tautological line bundle on $X$, with $(X,\xi) \cong (\mathbb P(\mathcal E), \mathcal O_{\mathbb P(\mathcal E)}(1))$, if and only if $\mathcal F$ is such that
\begin{equation}\label{needed to pullback}
\begin{array}{ccc}
  H^i(Y,\mathcal F)=0 & \text{and} & H^i(Y,\mathcal F(-c_1(\mathcal E)))=0, \; 0 \leqslant i \leqslant 2.
\end{array}
\end{equation} In particular, if $c_1(\mathcal E)$ is very ample on $Y$, then the rank $r$ vector bunde on $X$, $ \mathcal U=\xi \otimes \pi^*\mathcal F$, is Ulrich with respect to $\xi$ 
 if and only if the rank $r$ vector bundle on $Y$,  $\mathcal F (c_1(\mathcal E))$, is Ulrich with respect to $c_1(\mathcal E)$.

\label{ass:AB} Let $e \geqslant  0$, $b_e$, $k_e$ be integers such that
\begin{equation}\label{(iii)}
b_e-e< k_e< 2b_e-4e,
\end{equation} and let ${\mathcal E}_e$ be a rank-two vector bundle over $\mathbb{F}_e$, with
\begin{eqnarray*}
c_1({\mathcal E}_e) \equiv 3 C_e + b_e f \;\; {\rm and} \;\; c_2({\mathcal E}_e) = k_e,
\end{eqnarray*} which fits in the exact sequence 
\begin{equation}\label{eq:al-be}
0 \to A_e \to {\mathcal E}_e \to B_e \to 0,
\end{equation} where $A_e$ and $B_e$ are line bundles on $\mathbb{F}_e$ such that
\begin{equation}\label{eq:al-be3}
A_e \equiv 2 C_e + (2b_e-k_e-2e) f \;\; {\rm and} \;\; B_e \equiv C_e + (k_e - b_e + 2e) f
\end{equation}

\label{prop:LineB}  Let $e \geqslant 0$ be an integer and let $(X_e, \xi)$ be a $3$-fold scroll as above. Then $X_e$  does  not support any Ulrich line bundle  w.r.t.  $\xi$ unless $e = 0$, in which case the following are the unique Ulrich line bundles on $X_0$: 
\begin{itemize}
\item[(i)]  $L_1 :=\xi+\varphi^*\mathcal O_{\mathbb{F}_0}(2,-1) $ and  its Ulrich dual $ L_2 :=\xi+\varphi^*\mathcal O_{\mathbb{F}_0}(-1,b_0-1)$, with  $b_0 \geqslant 2$, see  \eqref{eq:rem:assAB}; 
\item[(ii)]  for any integer $t\geqslant  1$, $M_1 :=2\xi+\varphi^*\mathcal O_{\mathbb{F}_0}(-1,-t-1)$ and  its Ulrich dual \\$M_2:=\varphi^*\mathcal O_{\mathbb{F}_0}(2,3t-1)$,   which only occur for $b_0=2t, k_0=3t$.
\end{itemize}

(of Theorem \ref{prop:LineB}) Let ${\mathcal L} = a\xi + \varphi^*\mathcal O_{\mathbb{F}_e}(\alpha,\beta)$ be an Ulrich line bundle on $X_e$. From \cite[Corollary 2.2]{f-lc-pl} we know that $a=0, 1, 2$. 






\medskip

\noindent
{\bf Case I}: If $a=1$ then, by Theorem \ref{pullback}, ${\mathcal L} = \xi + \varphi^*\mathcal O_{\mathbb{F}_e}(\alpha,\beta)$ is Ulrich with respect to $\xi$ if and only if 
\begin{eqnarray*}
H^i(\mathbb{F}_e, \mathcal O_{\mathbb{F}_e}(\alpha,\beta) ) = H^i(\mathbb{F}_e, \mathcal O_{\mathbb{F}_e}(\alpha,\beta) -c_1({\mathcal E}_e)) =0
\quad  \text{for $i=0, 1, 2.$ }
 \end{eqnarray*} 
 Thus $\chi(\mathbb{F}_e, \mathcal O_{\mathbb{F}_e}(\alpha,\beta) )=\chi(\mathbb{F}_e, \mathcal O_{\mathbb{F}_e}(\alpha,\beta) - c_1({\mathcal E}_e))=0$. 
By Riemann-Roch we get, respectively,
\begin{eqnarray}
\label{eq1}
(\alpha +1)(e\alpha -2\beta-2)=0
\end{eqnarray} and 
\begin{eqnarray}
\label{eq2}
(\alpha-2)(e\alpha -2\beta+2b_e-3e-2)=0
\end{eqnarray} 
Thus either $\alpha=-1$ which, along with \eqref{eq2}, gives  $\beta=b_e-2e-1$ or  $\alpha=2$ which, along with \eqref{eq1}, gives  $\beta=e-1$.


We need to check that  $H^i(\mathbb{F}_e, \mathcal O_{\mathbb{F}_e}(\alpha,\beta) ) = H^i(\mathbb{F}_e, \mathcal O_{\mathbb{F}_e}(\alpha,\beta) -c_1(\mathcal{E}_e)) = 0$ \quad for $i\geqslant 0,$  with $(\alpha, \beta)=(-1, b_e-2e-1)$ or $(\alpha, \beta)=(2, e-1).$ 

If $e=0$  then the vanishings follow by the K{\"u}nneth formula, hence we get $\mathcal L=L_2$ in the first case whereas $\mathcal L=L_1$ in the latter case, where $L_1$ and $L_2$ are as in the statement. 

If  $e>0$, the cohomology groups are not all zero therefore there are no Ulrich line bundles with $a=1$ in these cases. 







\medskip

\noindent
{\bf Case II}:  If $a=2$ then, by \cite[Corollary 2.2]{f-lc-pl}, $\mathcal L = 2\xi + \varphi^*\mathcal O_{\mathbb{F}_e}(\alpha,\beta)$ is Ulrich with respect to $\xi$ if and only if 
\begin{eqnarray*}
H^i(\mathbb{F}_e, \mathcal O_{\mathbb{F}_e}(\alpha,\beta) ) = H^i(\mathbb{F}_e, \mathcal{E}_e(\mathcal O_{\mathbb{F}_e}(\alpha,\beta))) =0
\quad  \text{for $i=0, 1, 2.$}
 \end{eqnarray*} 
 Thus $\chi(\mathbb{F}_e, \mathcal O_{\mathbb{F}_e}(\alpha,\beta) )=\chi(\mathbb{F}_e,  \mathcal{E}_e(\mathcal O_{\mathbb{F}_e}(\alpha,\beta))))=0$.  By Riemann-Roch we get \eqref{eq1} and 
\begin{eqnarray} 
\label{eq3}
-e\alpha^2+2\alpha \beta+\alpha b_e-4e\alpha+2\alpha+5 \beta+4b_e-6e-k_e+5=0,
\end{eqnarray} 
respectively. From \eqref{eq1} either  $\alpha=-1$ or  $\beta=\frac{\alpha e}{2}-1.$

\medskip


{\bf Case II-a}: $\alpha=-1$. Plugging such value  in \eqref{eq3} we get 
 $\beta=-b_e+e+\frac{k_e}{3}-1$, which forces $k_e=3t$ for some $t\in  \mathbb{Z}$, hence $\beta=-b_e+e+t-1$.    We compute $H^i(\mathbb{F}_e, \mathcal O_{\mathbb{F}_e}(\alpha,\beta))=H^i(\mathbb{F}_e, \mathcal O_{\mathbb{F}_e}(-1,-b_e+e+t-1) )$ and  $H^i(\mathbb{F}_e, \mathcal{E}_e(\mathcal O_{\mathbb{F}_e}(-1,-b_e+e+t-1)))$ for $i=0, 1, 2.$



Now $R^{i}{\pi_e}_*(\mathcal O_{\mathbb{F}_e}(-1,-b_e+e+t-1))=0$, for $i\geqslant 0$, 
hence, from Leray's isomorphism we have  $H^i(\mathbb{F}_e, \mathcal O_{\mathbb{F}_e}(-1,-b_e+e+t-1) )\cong H^i(\mathbb P^1, 0 )=0$, for $i=0, 1, 2.$
\vspace{2mm}

To compute $H^i(\mathbb{F}_e, \mathcal{E}_e(\mathcal O_{\mathbb{F}_e}(-1,-b_e+e+t-1)))$
we recall that the vector bundle $\mathcal{E}_e$ sits in the exact sequence \eqref{eq:al-be}, where $A_e\in |\mathcal O_{\mathbb{F}_e}(2,2b_e-k_e-2e)|$ and $B_e\in  |\mathcal O_{\mathbb{F}_e}(1,k_e-b_e+2e)|$ and after twisting \eqref{eq:al-be} with $\mathcal O_{\mathbb{F}_e}(-1,-b_e+e+t-1)$ we have
\begin{equation}\label{eqtwist:al-be}
0 \to  \mathcal O_{\mathbb{F}_e}(1,b_e-2t-e-1)\to {\mathcal E}_e(\mathcal O_{\mathbb{F}_e}(-1,-b_e+e+t-1)) \to  \mathcal O_{\mathbb{F}_e}(0,4t-2b_e+3e-1) \to 0.
\end{equation}

Now 
\begin{eqnarray*}
\begin{aligned}
R^{i}{\pi_e}_*\mathcal O_{\mathbb{F}_e}(1,b_e-2t-e-1)=0, \quad \mbox{for $i>0$,  and} \\
{\pi_e}_*\mathcal O_{\mathbb{F}_e}(1,b_e-2t-e-1)\cong (\mathcal O_{\mathbb P^1} \oplus \mathcal O_{\mathbb P^1}(-e)) \otimes \mathcal O_{\mathbb P^1} (b_e-2t-e-1),
\end{aligned}
\end{eqnarray*}
hence, from Leray's isomorphism we have
\begin{eqnarray}
\label{coom a sinistra}
 \, \qquad\quad  H^i(\mathbb{F}_e,\mathcal O_{\mathbb{F}_e}(1,b_e-2t-e-1))\cong H^i(\mathbb P^1, (\mathcal O_{\mathbb P^1} \oplus \mathcal O_{\mathbb P^1}(-e))  (b_e-2t-e-1))\\ \nonumber
= H^i(\mathbb P^1, \mathcal O_{\mathbb P^1} (b_e-2t-e-1))\oplus H^i(\mathbb P^1, \mathcal O_{\mathbb P^1} (b_e-2t-2e-1)) 
\end{eqnarray} and similarly
\begin{eqnarray}
\label{coom a destra}
H^i(\mathbb{F}_e,  \mathcal O_{\mathbb{F}_e}(0,4t-2b_e+3e-1) )&\cong&H^i(\mathbb P^1, \mathcal O_{\mathbb P^1}(4t-2b_e+3e-1))
\end{eqnarray} 

We  consider first the case $e=0$ and then the case $e \geqslant 1$.








If  $e=0$, then \eqref{coom a sinistra} and \eqref{coom a destra} become
\begin{eqnarray*}
H^i(\mathbb{F}_0, \mathcal O_{\mathbb{F}_0}(1,b_0-2t-1))&=& H^i(\mathbb P^1, \mathcal O_{\mathbb P^1} (b_0-2t-1)^{\oplus 2}) 
\end{eqnarray*} 
\begin{eqnarray*}
H^i(\mathbb{F}_0,  \mathcal O_{\mathbb{F}_0}(0,4t-2b_0-1) )&=& H^i(\mathbb P^1, \mathcal O_{\mathbb P^1}(4t-2b_0-1))
\end{eqnarray*} 


If $b_0-2t-1\geqslant 0$ then 
\begin{eqnarray*}
h^0(\mathbb P^1, \mathcal O_{\mathbb P^1} (b_0-2t-1)^{\oplus 2}) &= &2(b_0-2t) \\
h^1(\mathbb P^1, \mathcal O_{\mathbb P^1} (b_0-2t-1)^{\oplus 2}) &= &0, \quad \text{by Serre's duality on $\mathbb P^1$.}
\end{eqnarray*}
Note that if  $b_0-2t-1\geqslant 0$ then                                                                                                                                
 $4t-2b_0-1 \leqslant -3$ hence $h^0(\mathbb P^1, \mathcal O_{\mathbb P^1}(4t-2b_0-1))=0$ and, by Serre duality, $h^1(\mathbb P^1, \mathcal O_{\mathbb P^1}(4t-2b_0-1))\cong h^0(\mathbb P^1, \mathcal O_{\mathbb P^1}(2b_0-4t-1))=2b_0-4t.$

These computations, along with the cohomology sequence associated to \eqref{eqtwist:al-be}, give 
\begin{eqnarray*}
h^i({\mathcal E}_0(\mathcal O_{\mathbb{F}_0}(-1,-b_0+t-1)))&=&2b_0-4t\geqslant 2 \, \mbox{(by assumption),  for $i=0,1$,}\\
h^2({\mathcal E}_0(\mathcal O_{\mathbb{F}_0}(-1,-b_0+t-1)))&=&0, \, \mbox{trivially.}
\end{eqnarray*}


If $b_0-2t-1< 0$ then 
\begin{eqnarray*}
h^0(\mathbb P^1, \mathcal O_{\mathbb P^1} (b_0-2t-1)^{\oplus 2}) &= &0 \\
h^1(\mathbb P^1, \mathcal O_{\mathbb P^1} (b_0-2t-1)^{\oplus 2})&\cong &2 h^0(\mathbb P^1, \mathcal O_{\mathbb P^1} (2t-b_0-1)), \quad \text{by Serre's duality on $\mathbb P^1$.}
\end{eqnarray*}
Note that 
\begin{eqnarray*}
h^0(\mathbb P^1, \mathcal O_{\mathbb P^1} (2t-b_0-1))= \left\{
    \begin{array}{ll}
      0 &   \mbox{ if $b_0=2t$}\\ 
       2t-b_0  & \mbox{ if $2t-b_0-1\geqslant 0$}.
    \end{array}
\right.
\end{eqnarray*}

Note also that  $b_0-2t-1< 0$ 

implies that   $4t-2b_0-1 \geqslant -2$, hence 

 if $4t-2b_0-1 \geqslant 0$,
  $h^0(\mathbb P^1, \mathcal O_{\mathbb P^1}(4t-2b_0-1))=4t-2b_0$ and $h^1(\mathbb P^1, \mathcal O_{\mathbb P^1}(4t-2b_0-1))=0;$

if $4t-2b_0-1 = -1$, $h^0(\mathbb P^1, \mathcal O_{\mathbb P^1}(4t-2b_0-1))=h^1(\mathbb P^1, \mathcal O_{\mathbb P^1}(4t-2b_0-1))=0;$

if $4t-2b_0-1 = -2$, $h^0(\mathbb P^1, \mathcal O_{\mathbb P^1}(4t-2b_0-1))=0$ and $h^1(\mathbb P^1, \mathcal O_{\mathbb P^1}(4t-2b_0-1))=1$.

These facts, along with \eqref{eqtwist:al-be}, give that 
\begin{eqnarray*}
 h^i({\mathcal E}_0(\mathcal O_{\mathbb{F}_0}(-1,-b_0+t-1)))= 0,\, \mbox{ for $i=0,1,2$, \quad if $b_0=2t$, }\\
 h^0({\mathcal E}_0(\mathcal O_{\mathbb{F}_0}(-1,-b_0+t-1)))\neq 0, \, \mbox{in the remaining two cases}, 
\end{eqnarray*}  
the latter case holds because otherwise from the cohomology sequence associated to  \eqref{eqtwist:al-be}  it would follow that  $h^1({\mathcal E}_0(\mathcal O_{\mathbb{F}_0}(-1,-b_0+t-1)))< 0$, which is impossible. 
Thus we are left with the cases $b_0=2t, k_0=3t$, where $t \geqslant 1$, as it follows from   \eqref{(iii)} and \eqref{eq:rem:assAB}. 
Hence in this case we get  $\mathcal L=M_1$   is Ulrich and its Ulrich dual  is  $M_2$.

\smallskip






If $e \geqslant 1$ in order to compute the cohomology groups in \eqref{coom a sinistra} and \eqref{coom a destra} we consider first the case in which $b_e-2t-2e-1 \geqslant 0.$ Note that in this case also $b_e-2t-e-1 \geqslant 0$ and thus  in \eqref{coom a sinistra} we have
\begin{eqnarray*}
h^0(\mathbb{F}_e,\mathcal O_{\mathbb{F}_e}(1,b_e-2t-e-1)) = h^0(\mathbb P^1, (\mathcal O_{\mathbb P^1} \oplus \mathcal O_{\mathbb P^1}(-e))  (b_e-2t-e-1))&=&2b_e-4t-3e, \\ 
h^1(\mathbb{F}_e,\mathcal O_{\mathbb{F}_e}(1,b_e-2t-e-1))=h^1(\mathbb P^1, (\mathcal O_{\mathbb P^1} \oplus \mathcal O_{\mathbb P^1}(-e))  (b_e-2t-e-1))&=&0.
\end{eqnarray*}
As for \eqref{coom a destra} note that 

$4t-2b_e+3e-1 \leqslant -3-e$, by assumption, and thus  
\begin{eqnarray*}
H^0(\mathbb{F}_e,  \mathcal O_{\mathbb{F}_e}(0,4t-2b_e+3e-1) )&\cong&H^0(\mathbb P^1, \mathcal O_{\mathbb P^1}(4t-2b_e+3e-1))=0 \quad \mbox{and}\\
h^1(\mathbb P^1, \mathcal O_{\mathbb P^1}(4t-2b_e+3e-1)))&=&h^0(\mathbb P^1, \mathcal O_{\mathbb P^1}(2b_e-4t-3e-1)))=2b_e-4t-3e.
\end{eqnarray*}

From the cohomology sequence associated to \eqref{eqtwist:al-be} it follows that 
\begin{eqnarray*}
h^0({\mathcal E}_e(\mathcal O_{\mathbb{F}_e}(-1,-b_e+e+t-1)))&=&h^1({\mathcal E}_e(\mathcal O_{\mathbb{F}_e}(-1,-b_e+e+t-1)))\\
&=&2b_e-4t-3e \geqslant 2+e,
\end{eqnarray*}
because $4t-2b_e+3e-1\leqslant -3-e$.

If  $b_e-2t-e-1 \geqslant 0$ and $b_e-2t-2e-1 < 0$ (the case $b_e-2t-2e-1 \geqslant 0$ was just treated), then 
\begin{eqnarray*}
h^0(\mathbb{F}_e,\mathcal O_{\mathbb{F}_e}(1,b_e-2t-e-1))&=&h^0(\mathbb P^1, (\mathcal O_{\mathbb P^1} \oplus \mathcal O_{\mathbb P^1}(-e))  (b_e-2t-e-1))\\&=&b_e-2t-e\geqslant 1.  
\end{eqnarray*}
Thus
 $h^0({\mathcal E}_e(\mathcal O_{\mathbb{F}_e}(-1,-b_e+e+t-1))\geqslant h^0(\mathbb{F}_e,\mathcal O_{\mathbb{F}_e}(1,b_e-2t-e-1))= b_e-2t-e\geqslant 1$. 


\medskip








{\bf Case II-b: } $\beta=\frac{\alpha e}{2}-1.$  Plugging such value in \eqref{eq3} we get 
\begin{eqnarray}\label{alfa}
\alpha=\frac{-8b_e+12e+2k_e}{2b_e-3e}
\end{eqnarray}
which implies that 
\begin{eqnarray*}
(\alpha+4) (2b_e-3e)=2k_e.
\end{eqnarray*}
 By  \eqref{(iii)} and \eqref{eq:rem:assAB},   we get $2b_e-3e\geqslant 3e+4\geqslant 2$ and  $k_e> b_e-e\geqslant 2e+2$. Thus $\alpha+4 >0$, that is $\alpha \geqslant -3$.
Notice that if $\alpha =-3$ then \eqref{alfa} gives $b_e=\frac{3}{2}e+k_e= \frac{1}{2}e+e+k_e> \frac{1}{2}e+b_e$ by  \eqref{(iii)}, which is a contradiction. Hence $\alpha \geqslant -2$ and therefore from \eqref{alfa}
it follows that $k_e \geqslant 2b_e-3e$ which contradicts the condition $k_e< 2b_e-4e$ in  \eqref{(iii)}.

\medskip

The proof is complete since the case $a=0$ is the Ulrich dual of the case $a=2$.

We consider  non--trivial extensions \eqref{extension1} as in {\bf Case L}; recall that $\dim {\rm Ext}^1(L_2,L_1)=4b_0-4\geqslant 4$,  being  $b_0 \geqslant 2$, 
and  moreover that a general vector bundle $\mathcal{F}_1$ arising from a general extension as in \eqref{extension1} is Ulrich w.r.t. $\xi$. 

Moreover, since $\mu(L_1) = \mu(L_2) = 8b_0 - k_0 -3$, as computed in \S\,\ref{S:subs41}-{\bf Case L}, one has $\mu(\mathcal{F}_1) = 8b_0 - k_0 -3$ and furthermore, since $L_1$ and $L_2$ are slope--stable, of the same slope and non--isomorphic line bundles, by \cite[Lemma\,4.2]{c-h-g-s}, $\mathcal F_1$ is simple, that is $h^0(\mathcal{F}_1\otimes\mathcal{F}_1^{\vee}) = 1$, in particular it is indecomposable. 


We now want to show that  $h^2(\mathcal{F}_1\otimes\mathcal{F}_1^{\vee}) = 0 = h^3(\mathcal{F}_1\otimes\mathcal{F}_1^{\vee})$ and that 
$\chi(\mathcal{F}_1\otimes\mathcal{F}_1^{\vee})=-6b_0+3$. Tensoring \eqref{extension1} with $\mathcal{F}_1^{\vee}$ we get
\begin{eqnarray}
\label{extension1tensorFdual}
0 \to L_1 \otimes \mathcal{F}_1^{\vee}   \to \mathcal{F}_1\otimes \mathcal{F}_1^{\vee} \to  L_2 \otimes \mathcal{F}_1^{\vee} \to 0.
\end{eqnarray} Dualizing \eqref{extension1} gives the following exact sequence
\begin{eqnarray}
\label{extension1dual}
0 \to L_2^{\vee}  \to \mathcal{F}_1^{\vee} \to L_1^{\vee}\ \to 0
\end{eqnarray} Tensoring \eqref{extension1dual} with $L_1$ and $L_2$, respectively, gives
\begin{eqnarray}
\label{extension1dualL1}
0 \to L_2^{\vee}\otimes L_1(= \varphi^*\mathcal O_{\mathbb{F}_0}(3,-b_0)) \to L_1 \otimes \mathcal{F}_1^{\vee} \to {\mathcal{O}}_{X_0} \to 0
\end{eqnarray} 
\begin{eqnarray}
\label{extension1dualL2}
0 \to  {\mathcal{O}}_{X_0} \to L_2 \otimes \mathcal{F}_1^{\vee} \to L_2 \otimes L_1^{\vee}(=\varphi^*\mathcal O_{\mathbb{F}_0}(-3,b_0)) \to 0
\end{eqnarray} 

Because  $\mathcal{F}_1$ is simple, then $h^0(X,  \mathcal{F}_1\otimes \mathcal{F}_1^{\vee} )=1$. The remaining cohomology $H^i(X,  \mathcal{F}_1\otimes \mathcal{F}_1^{\vee} )$  can be easily computed from the cohomology sequence associated to \eqref{extension1dualL1} and \eqref{extension1dualL2}.  Clearly $h^i(\mathcal{O}_{X_0})=0$ if $i\geqslant 1$ and  $h^0(\mathcal{O}_{X_0})=1$. It remains to compute 
$H^i( \varphi^*\mathcal O_{\mathbb{F}_0}(3,-b_0))$ and $H^i( \varphi^*\mathcal O_{\mathbb{F}_0}(-3,b_0)).$ 
 \begin{eqnarray}\label{eq:calcoliutili}
 H^i(X_0, \varphi^*\mathcal O_{\mathbb{F}_0}(3,-b_0))&\cong &H^i(\mathbb{F}_0, \mathcal O_{\mathbb{F}_0}(3,-b_0))\cong H^i(\mathbb P^1, S^3(\mathcal O_{\mathbb P^1}\oplus \mathcal O_{\mathbb P^1})(-b_0)) \\
 &&  H^i(\mathbb P^1, \mathcal O^{\oplus 4}(-b_0))=\left\{
    \begin{array}{ll}
0 &\mbox{ if $i=0,2,3$}\\
     4b_0-4&   \mbox{ if  $i=1$}
    \end{array}
\right.\nonumber
 \end{eqnarray}
 Similarly
 \begin{eqnarray}\label{eq:calcoliutili2}
 H^i(X, \varphi^*\mathcal O_{\mathbb{F}_0}(-3,b_0))&\cong &H^i(\mathbb{F}_0, \mathcal O_{\mathbb{F}_0}(-3,b_0))\cong H^{2-i}((\mathbb{F}_0, \mathcal O_{\mathbb{F}_0}(1,-2-b_0))\\
 &&H^{2-i}(\mathbb P^1, \mathcal O_{\mathbb P^1}^{\oplus 2}(-2-b_0)) =\left\{
    \begin{array}{ll}
0 &\mbox{ if $i=0,2,3$}\\
     2b_0+2&   \mbox{ if  $i=1$}
    \end{array}
\right.\nonumber
 \end{eqnarray} It thus follows that $h^2(\mathcal{F}_1\otimes\mathcal{F}_1^{\vee}) = 0 = h^3(\mathcal{F}_1\otimes\mathcal{F}_1^{\vee})$. From \eqref{extension1tensorFdual} we have that 
\begin{eqnarray*}\chi(\mathcal{F}_1\otimes \mathcal{F}_1^{\vee} )=\chi( L_1 \otimes \mathcal{F}_1^{\vee})+\chi(L_2 \otimes \mathcal{F}_1^{\vee})=-6b_0+4.
\end{eqnarray*}


Since $\mathcal{F}_1$ is simple with $h^2(\mathcal{F}_1\otimes \mathcal{F}_1^{\vee}) = 0$, by \cite[Proposition 2.10]{c-h-g-s} there exists a smooth modular family 
containing the point $[\mathcal{F}_1]$. Furthermore, since $\mathcal{F}_1$ is Ulrich, with Chern classes 
$$c_1(\mathcal{F}_1)=2\xi+\varphi^*\mathcal O_{\mathbb{F}_0}(1,b_0-2) \;\; {\rm and} \;\; c_2(\mathcal{F}_1)=\xi \cdot \varphi^*\mathcal O_{\mathbb{F}_0}(4,2b_0-2) +(2b_0-k_0-1)F,$$as computed in \S\,\ref{S:subs41}--{\bf Case L}, 
the general point $[\mathcal{U}]$ of the smooth modular family to which $[\mathcal{F}_1]$ belongs corresponds to an Ulrich rank two vector bundles with same Chern classes as above, i.e. 
as in \eqref{eq:chern20}, as it follows from the facts that Ulrichness is an open condition (by semi-continuity) and that Chern classes are invariants 
on irreducible families. 


We want to show that $\mathcal{U}$ is also slope--stable w.r.t. $\xi$. By Theorem \ref{thm:stab}--(b) (cf. also \cite[Sect 3, (3.2)]{b}), if $ \mathcal{U} $ were not a stable bundle, it would be presented as an extension of Ulrich line bundles on $X_0$. In such a case, by the classification of Ulrich line bundles given in Theorem \ref{prop:LineB} and all the possible extensions computed in \S\,\ref{S:subs41}-{\bf Case M} or {\bf Case L-M}, we see that the only possibilities for $\mathcal{U}$ to arise as an extension of Ulrich line bundles should be extensions either \eqref{extension1} or  \eqref{extension1'}, by Chern classes reasons. 
In both cases the dimension of (the projectivization) of the corresponding families of extensions are either $4b_0 -5$ or $2b_0+1$. On the other hand, by semi-continuity on the smooth modular family, 
one has 
$$h^j(\mathcal{U}\otimes \mathcal{U}^{\vee}) = h^j(\mathcal{F}_1\otimes \mathcal{F}_1^{\vee}) = 0, \; 2 \leqslant j \leqslant 3, \; {\rm and} \; h^0(\mathcal{U}\otimes \mathcal{U}^{\vee}) = h^0(\mathcal{F}_1\otimes \mathcal{F}_1^{\vee}) = 1,$$thus
$$ h^1(\mathcal{U}\otimes \mathcal{U}^{\vee}) = 1 - \chi (\mathcal{U}\otimes \mathcal{U}^{\vee} ) = 1 - \chi(\mathcal{F}_1\otimes \mathcal{F}_1^{\vee}) = h^1(\mathcal{F}_1\otimes \mathcal{F}_1^{\vee}) = 6b_0-3,$$as computed above.  In other words, 
the smooth modular family whose general point is $[\mathcal{U}]$ is of dimension $6b_0 -3$, which is bigger than $4b_0-5$ and $2 b_0 +1$,  for any $b_0 \geqslant 2$. This shows 
that $[\mathcal{U}]$ general corresponds to a stable, and so also slope-stable bundle  (cf. Theorem \ref{thm:stab}-(c) above).

By slope-stability of $\mathcal{U}$, we deduce that the moduli space of rank two Ulrich bundles with Chern classes as in \eqref{eq:chern20} is not empty and it contains a generically smooth 
component $\mathcal M$, of dimension $6b_0-3$ whose general point $[\mathcal{U}] \in \mathcal M$ is also slope-stable, whose slope w.r.t. $\xi$ is 
$\mu(\mathcal{U}) = \frac{c_1(\mathcal{U}) \cdot \xi^2}{2} = 8b_0 - k_0 -3$,  as $c_1( \mathcal{U} ) = c_1(\mathcal{F}_1)$. 



Finally, note that  
\begin{eqnarray*}K_{X_0}+4\xi&=&-2\xi+\varphi^*\mathcal O_{\mathbb{F}_0}(-2,-2)+\varphi^*\mathcal O_{\mathbb{F}_0}(3,b_0)+4\xi=2\xi+\varphi^*\mathcal O_{\mathbb{F}_0}(1,b_0-2)\\&=&c_1(\mathcal{F}_1) = c_1(\mathcal{U}).
\end{eqnarray*} This, together with the fact that $\mathcal{U}$ is of rank two, gives 
$$\mathcal{U}^{\vee} \cong \mathcal{U}(- c_1(\mathcal{U})) = \mathcal{U} (-K_{X_0} - 4 \xi),$$i.e. that $\mathcal{U}^{\vee}(K_{X_0} + 4 \xi) \cong \mathcal{U}$ in other words 
$\mathcal{U}$ is isomorphic to its Ulrich dual bundle, i.e. $\mathcal{U} $ is special, as stated.

\label{thm:rk 2 vctB e>0}    Let  $(X_e, \xi) \cong (\mathbb{ P}({\mathcal E_e}),{\mathcal O}_{\mathbb{P}({\mathcalE_e})}(1))$ be a $3$-fold  scroll over $\mathbb{F}_e$, with $e> 0$,  and $\mathcal E_e$ be as in Assumptions \ref{ass:AB}. Let $\varphi: X_e \to \mathbb{F}_e$ be the scroll map and $F$ be the $\varphi$- fibre. Then the moduli space of  rank two vector bundles $ \mathcal{U} $ on $X_e$,  which are Ulrich w.r.t. $\xi$, with Chern classes
\begin{equation}\label{eq:chern2e}
c_1( \mathcal{U} )=2\xi+\varphi^*\mathcal O_{\mathbb{F}_e}(1,b_e-e-2) \;\; {\rm and} \;\;  c_2( \mathcal{U} ) = \xi \varphi^*\mathcal O_{F_e}(4,2b_e-e-2) + (2b_e-3e-k_e-1) F,
\end{equation}
is not empty and it contains a generically smooth component $\mathcal M$ of dimension 

$$ \dim(\mathcal M) = 6b_e-9e-3,$$
whose general point $[ \mathcal{U} ]$ 
corresponds to a  special and slope-stable vector bundle of slope w.r.t. $\xi$ \linebreak
\begin{eqnarray}\label{eq:slope2e}
\mu( \mathcal{U} ) = 8 b_e - k_e - 12 e - 3.
\end{eqnarray}

By \cite[Theorem 3.4]{a-c-mr}, we know that there exist  rank two vector bundles $\mathcal H_1$ on $\mathbb{F}_e$, which are  Ulrich with respect to  $c_1({\mathcal E}_e) =\mathcal O_{\mathbb{F}_e}(3, b_e)$,  given by extensions
\begin{eqnarray}
\label{extensionsuFe}
0 \to \mathcal O_{\mathbb{F}_e}(3 , b_e-1)  \to \mathcal{H}_1 \to I_Z\otimes \mathcal O_{\mathbb{F}_e}(4, 2b_e-1-e)  \to 0, 
\end{eqnarray} where $Z$ is a general zero-dimensional subscheme of $\mathbb{F}_e$ of length $\ell(Z)=2b_e-3e$.
Such a bundle $\mathcal{H}_1$ is stable,  cf. \cite[Remark 3.7]{a-c-mr},  hence simple, that is $h^0(\mathcal{H}_1 \otimes \mathcal{H}_1^{\vee})=1$, and indecomposable.

Set $\mathcal{H}:=  \mathcal{H}_1(-c_1({\mathcal E}_e))$, which is stable being a twist of a stable vector bundle,  so it is also simple, i.e. 
$h^0(\mathcal{H} \otimes \mathcal{H}^{\vee})=1$. By Theorem \ref{pullback} the vector bundle 
$ \mathcal{V} : = \xi \otimes \varphi^*(\mathcal{H})$ is a rank two vector bundle on  $X_e$ which is Ulrich with respect to $\xi$.  

From \eqref{extensionsuFe} we see that $c_1(\mathcal{H})= \mathcal O_{\mathbb{F}_e}(1 , b_e-e-2)$ and $c_2(\mathcal{H})=2b_e-3e-1$. Easy Chern classes computations give that  
\begin{eqnarray*}
c_1( \mathcal{V} ) = 2\xi+\varphi^*\mathcal O_{\mathbb{F}_e}(1,b_e-e-2) \;\; {\rm and} \;\; c_2( \mathcal{V} ) = \xi \varphi^*\mathcal O_{F_e}(4,2b_e-e-2) + (2b_e-3e-k_e-1) F.
\end{eqnarray*} 
Moreover by Theorem \ref{thm:stab}--(b) (cf.\;also \cite[Sect 3, (3.2)]{b}) such a bundle $ \mathcal{V} $  is stable,  so also slope-stable by Theorem \ref{thm:stab}-(c),  since there are no Ulrich line bundles on $(X_e, \xi) $ as it follows from Theorem \ref{prop:LineB}. 

Our next step is to compute the cohomology groups $H^i(X_e,  \mathcal{V} \otimes\mathcal{V}^{\vee} )$ \,  for $i=0,1,2,3$. Because $H^i(X_e,   \mathcal{V} \otimes\mathcal{V}^{\vee} ) = H^i(X_e,  \varphi^*(\mathcal{H}\otimes \mathcal{H}^{\vee}))\cong H^i(\mathbb{F}_e, \mathcal{H}\otimes \mathcal{H}^{\vee})$ we will focus on computations of $H^i(\mathbb{F}_e, \mathcal{H}\otimes \mathcal{H}^{\vee})$, $i=0,1,2,3$. 

First of all $ h^3(\mathbb{F}_e, \mathcal{H}\otimes \mathcal{H}^{\vee}) = 0$, as $\mathbb{F}_e$ is a surface, and $ h^0(\mathbb{F}_e, \mathcal{H}\otimes \mathcal{H}^{\vee}) = 1$, as $\mathcal{H}$ is simple. 
For the other cohomology groups, we  tensor \eqref{extensionsuFe} with $-c_1({\mathcal E}_e)=\mathcal O_{{\mathbb F}_e}(-3,-b_e)$ and we get
\begin{eqnarray}
\label{extensionsuFe twisted}
0 \to \mathcal O_{\mathbb{F}_e}(0 , -1)  \to \mathcal{H} \to I_Z\otimes \mathcal O_{\mathbb{F}_e}(1, b_e-1-e)  \to 0.
\end{eqnarray} 
Because $\mathcal{H}$ is of rank $2$ and $c_1(\mathcal{H})=\mathcal O_{\mathbb{F}_e}(1 , b_e-2-e)$, we have that 
$ \mathcal{H}^{\vee}\cong \mathcal{H}\otimes \mathcal O_{\mathbb{F}_e}(-1 , -b_e+2+e)$ and thus after tensoring \eqref{extensionsuFe twisted} with $\mathcal{H}^{\vee} $ we get
\begin{eqnarray}
\label{extensionsuFe twisted Hdual}
0 \to\mathcal{H} \otimes  \mathcal O_{\mathbb{F}_e}(-1 , 1+e-b_e)  \to \mathcal{H} \otimes \mathcal{H}^{\vee} \to I_Z\otimes \mathcal{H}\otimes \mathcal O_{\mathbb{F}_e}(0, 1)  \to 0.
\end{eqnarray} 
In order to compute the cohomology groups of $\mathcal{H} \otimes  \mathcal O_{\mathbb{F}_e}(-1 , 1+e-b_e)$ we will use the short exact sequence \eqref{extensionsuFe twisted} twisted with $\mathcal O_{\mathbb{F}_e}(-1 , 1+e-b_e)$
which gives 
\begin{eqnarray}
\label{extensionsuFe twisted O(-1,1+e-b)}
0 \to  \mathcal O_{\mathbb{F}_e}(-1 , e-b_e)  \to \mathcal{H} \otimes  \mathcal O_{\mathbb{F}_e}(-1 , 1+e-b_e)\to I_Z
\to 0.
\end{eqnarray} 
From this we can easily see that $H^0(\mathcal{F}\otimes  \mathcal O_{\mathbb{F}_e}(-1 , 1+e-b_e))=0=H^2(\mathcal{F}\otimes  \mathcal O_{\mathbb{F}_e}(-1 , 1+e-b_e))$ and $h^1(\mathcal{F}\otimes  \mathcal O_{\mathbb{F}_e}(-1 , 1+e-b_e))=2b_e-3e-1$.

Our next task is to compute the  cohomology groups of $I_Z\otimes \mathcal{H} \otimes \mathcal O_{\mathbb{F}_e}(0, 1)$. We tensor the sequence 
\begin{eqnarray*}
0 \to  I_Z \to \mathcal O_{\mathbb{F}_e} \to \mathcal O_Z  \to 0 
\end{eqnarray*}
with $\mathcal{H} \otimes \mathcal O_{\mathbb{F}_e}(0, 1)$  and $\mathcal O_{\mathbb{F}_e}(1 , b_e-e)$, respectively, and we get \begin{eqnarray}
\label{exact4}
0 \to  I_Z\otimes \mathcal{H} \otimes \mathcal O_{\mathbb{F}_e}(0, 1)  \to \mathcal{H} \otimes  \mathcal O_{\mathbb{F}_e}(0 , 1)\to (\mathcal{H} \otimes  \mathcal O_{\mathbb{F}_e}(0 , 1))_{|Z}
\to 0
\end{eqnarray}
\begin{eqnarray}
\label{exact5}
0 \to  I_Z\otimes \mathcal O_{\mathbb{F}_e}(1,  b_e-e)  \to \mathcal O_{\mathbb{F}_e}(1,  b_e-e)\to \mathcal O_{Z}
\to 0.
\end{eqnarray}
 We  tensor \eqref{extensionsuFe twisted} with $\mathcal O_{\mathbb{F}_e}(0 , 1
 )$ and we get
 \begin{eqnarray}
\label{exact6}
0 \to  \mathcal O_{\mathbb{F}_e}  \to \mathcal{H} \otimes  \mathcal O_{\mathbb{F}_e}(0 , 1)\to   I_Z\otimes  \mathcal O_{\mathbb{F}_e}(1, b_e-e) 
\to 0.
\end{eqnarray}
Now use the cohomology sequence associated to the short exact sequences \eqref{exact4}, \eqref{exact5} and \eqref{exact6}.
Note that 
\begin{align*}
h^0(\mathbb{F}_e,\mathcal O_{\mathbb{F}_e}(1, b_e-e))\cong  h^0(\mathbb P^1,\mathcal O_{\mathbb P^1}(b_e-e)\oplus \mathcal O_{\mathbb P^1}(b_e-2e))= 2b_e-3e+2, 
\end{align*}
 and  
\begin{align*}
h^i(\mathbb{F}_e,\mathcal O_{\mathbb{F}_e}(1, b_e-e))\cong  h^i(\mathbb P^1,\mathcal O_{\mathbb P^1}(b_e-e)\oplus \mathcal O_{\mathbb P^1}(b_e-2e))=0 \quad \text{for $i=1,2$ }
\end{align*} 
because  Assumptions \ref{ass:AB} forces $b_e \geqslant 3e +2$). Notice that $\dim (|\mathcal O_{\mathbb{F}_e}(1, b_e-e)|)=2b_e-3e+1$,  so $h^0( I_Z\otimes  \mathcal O_{\mathbb{F}_e}(1, b_e-e))=2$ , being $Z$  general of length $\ell(Z)=2b_e-3e$. Therefore from 
\eqref{exact5} it follows that $h^i( I_Z\otimes  \mathcal O_{\mathbb{F}_e}(1, b_e-e))=0$ for $i=1,2$. Now using \eqref{exact6} it follows that $h^0(\mathbb{F}_e,\mathcal{H} \otimes \mathcal O_{\mathbb{F}_e}(0, 1))=3$ and  $h^i(\mathbb{F}_e,\mathcal{H} \otimes \mathcal O_{\mathbb{F}_e}(0, 1))=0$ for $i=1,2$. Thus $h^2(I_Z\otimes \mathcal{H}\otimes \mathcal O_{\mathbb{F}_e}(0, 1))=0$ and this, combined with  the cohomology sequence associated to \eqref{extensionsuFe twisted Hdual}, gives that $h^2( \mathcal{H}\otimes   \mathcal{H}^{\vee})=0$.

Thus from \eqref{exact4}, since $h^0(\mathbb{F}_e, (\mathcal{H}\otimes  \mathcal O_{\mathbb{F}_e}(0 ,1))_{|Z}
)=2(2b_2-3e)$ and $h^i(\mathbb{F}_e, \mathcal{H}\otimes  \mathcal O_{\mathbb{F}_e}(0 , 1)_{|Z}
)=0$ for $i=1,2$, it follows that $\chi(I_Z\otimes \mathcal{H}\otimes \mathcal O_{\mathbb{F}_e}(0, 1) )=\chi(\mathcal{H}\otimes \mathcal O_{\mathbb{F}_e}(0 , 1))-\chi( \mathcal{H}\otimes  \mathcal O_{\mathbb{F}_e}(0 , 1)_{|Z})=3-4b_e+6e.$
From the cohomology sequence associated to \eqref{extensionsuFe twisted Hdual} it follows that $\chi( \mathcal{H}\otimes   \mathcal{H}^{\vee} )=\chi(I_Z\otimes \mathcal{H}\otimes \mathcal O_{\mathbb{F}_e}(0, 1) )+\chi(\mathcal{H} \otimes  \mathcal O_{\mathbb{F}_e}(-1 , 1+e-b_e) )=3-4b_e+6e-2b_2+3e+1=4-6b_e+9e$ and thus $h^1( \mathcal{H}\otimes   \mathcal{H}^{\vee})=1-\chi( \mathcal{H}\otimes   \mathcal{H}^{\vee})=6b_e-9e-3$.

As already observed,  $H^i(X_e, \mathcal{V} \otimes\mathcal{V}^{\vee} )\cong H^i(\mathbb{F}_e, \mathcal H\otimes \mathcal H^{\vee})$, $i=0,1,2,3$, 
hence the above computations  give us the dimensions of all the cohomology groups $H^i(X_e, \mathcal{V} \otimes\mathcal{V}^{\vee})$, $i=0,1,2,3$.

By \cite[Proposition 2.10]{c-h-g-s}, since $h^2( \mathcal{V}  \otimes \mathcal{V}^{\vee}) = 0$ and $\mathcal{V}$ is simple, it follows that $\mathcal{V}$ admits 
a smooth modular family giving rise to a component $\mathcal M$ of the moduli space of rank two Ulrich vector bundles with Chern classes  
$$c_1( \mathcal{V})=2\xi+\varphi^*\mathcal O_{\mathbb{F}_e}(1,b_e-2-e)\;{\rm and}\; c_2( \mathcal{V} )=\xi \varphi^*\mathcal O_{\mathbb{F}_e}(4,b_e-2-e) +(2b_e-3e-k_e-1)F.$$Moreover, since $\mathcal{V}$ is 
slope-stable, it corresponds to a smooth point $[\mathcal{V}]$ of such a component $\mathcal M$ such that, 
$\dim (\mathcal M) = h^1(\mathcal{V}  \otimes \mathcal{V}^{\vee} )  = 6 b_e-9e-3$, as stated. 

Since Ulrichness, slope-stability, simplicity are open  conditions as well as Chern classes are constant for vector bundles varying in $\mathcal M$, it follows that  all the properties satisfied by $\mathcal V$ hold true  for the general member $[\mathcal{U} ] \in \mathcal M$, 
in particular $\mathcal M$ is also generically smooth. 


Note further that  $K_{X_e}+4\xi=-2\xi+\varphi^*\mathcal O_{\mathbb{F}_e}(-2,-2-e)+\varphi^*\mathcal O_{\mathbb{F}_e}(3,b_e)+4\xi=2\xi+\varphi^*\mathcal O_{\mathbb{F}_0}(1,b_e-e-2)=c_1(\mathcal{V})$, 
thus $ \mathcal{U} $ is  a special Ulrich bundle.  Finally, the slope of $ \mathcal{U} $ with respect to $\xi$ is 
\begin{eqnarray*}
\mu( \mathcal{U} ) = \frac{c_1( \mathcal{U} ) \cdot \xi^2}{2} = \frac{(2\xi+\varphi^*\mathcal O_{\mathbb{F}_e}(1,b_e-e-2) ) \cdot \xi^2}{2} = 8b_e - k_e - 12 e - 3.
\end{eqnarray*}

